import{_ as i,A as d,o as n,c as p,O as t,b as g,w as o,Z as a,E as e,a as l}from"./chunks/framework.2c2d5a61.js";const A=JSON.parse('{"title":"MySQL","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/05-MySQL.md","filePath":"interview/后端/Java/05-MySQL.md","lastUpdated":1789026500000}'),E={name:"interview/后端/Java/05-MySQL.md"};function L(h,r,N,c,I,u){const s=d("Mermaid");return n(),p("div",null,[r[2]||(r[2]=t('<h1 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-innodb-与-myisam-区别-★★★" tabindex="-1">1. InnoDB 与 MyISAM 区别 ★★★ <a class="header-anchor" href="#_1-innodb-与-myisam-区别-★★★" aria-label="Permalink to &quot;1. InnoDB 与 MyISAM 区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>InnoDB</strong> 支持<strong>事务</strong>、<strong>行级锁</strong>、外键、崩溃恢复，索引是<strong>聚簇</strong>的（数据即索引）；<strong>MyISAM</strong> 都不支持，只有<strong>表级锁</strong>、索引和数据分离，但无事务开销所以某些只读查询略快。MySQL 5.5 之后默认就是 InnoDB。一句话：生产一律 InnoDB。</p><p><strong>我的项目关联</strong> 我们全部表都是 <strong>InnoDB</strong>，没得选——订单、支付、对账这些都要<strong>事务</strong>，<strong>MyISAM</strong> 根本不能用。这条基本是<strong>送分题</strong>，记住「要事务就 InnoDB」即可。</p><p><strong>面试答题话术</strong> 「<strong>InnoDB</strong> 有<strong>事务</strong>、行锁、外键、崩溃恢复，索引是<strong>聚簇</strong>的；<strong>MyISAM</strong> 没事务、<strong>表锁</strong>、索引数据分离。MySQL 5.5 之后默认 InnoDB，生产上只要涉及事务就只能 InnoDB，我们项目全是它。」</p><hr><h2 id="_2-索引为什么用-b-树-★★★" tabindex="-1">2. 索引为什么用 B+ 树 ★★★ <a class="header-anchor" href="#_2-索引为什么用-b-树-★★★" aria-label="Permalink to &quot;2. 索引为什么用 B+ 树 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 哈希不支持<strong>范围查询</strong>和排序；二叉搜索树/<strong>红黑树</strong>太高，<strong>磁盘 IO</strong> 次数跟着树高走；<strong>B 树</strong>每个节点既存索引又存数据，一页能放的索引少，树也高。<strong>B+ 树</strong>则是「非叶子只存索引、数据全在叶子」，一页能塞更多索引，树更矮（<strong>3 层</strong>能存千万级）；叶子节点还用<strong>双向链表</strong>连起来，天然支持范围和排序。</p><p><strong>我的项目关联</strong> 知道「<strong>B+ 树</strong>矮、叶子有<strong>链表</strong>、支持<strong>范围查询</strong>」这个结论就够。我们的查询大量是「按桩编号 + 时间范围查订单」，正好吃 B+ 树<strong>范围扫描</strong>的红利，这也是为什么时间字段要进<strong>联合索引</strong>。</p><p><strong>面试答题话术</strong> 「选 <strong>B+ 树</strong>的核心是<strong>磁盘 IO</strong>：树越矮 IO 越少。B+ 树非叶子只存索引、能塞更多，所以树矮；数据全在叶子，叶子之间还有<strong>链表</strong>，<strong>范围查询</strong>和排序天然支持。哈希不能范围查，二叉树太高。项目里订单按桩加时间范围查，就靠叶子的链表顺序扫。」</p><hr><h2 id="_3-聚簇索引、回表、覆盖索引-★★★" tabindex="-1">3. 聚簇索引、回表、覆盖索引 ★★★ <a class="header-anchor" href="#_3-聚簇索引、回表、覆盖索引-★★★" aria-label="Permalink to &quot;3. 聚簇索引、回表、覆盖索引 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>聚簇索引</strong>（主键索引）的叶子存整行数据，一张表只能有一个。<strong>二级索引</strong>的叶子存「索引列 + 主键值」，所以用它查完还得拿主键回聚簇索引捞整行，这叫<strong>回表</strong>。如果查的列全在二级索引里，就不用回表，这就是<strong>覆盖索引</strong>，性能最好。另外主键建议<strong>自增</strong>：顺序插入减少<strong>页分裂</strong>，<strong>UUID</strong> 随机插入会频繁页分裂、出碎片。</p><p><strong>我的项目关联</strong> 优化时最常用的手段就是<strong>覆盖索引</strong>。比如「按桩编号 + 时间查订单状态」，我把要查的字段一起放进<strong>联合索引</strong>，就能避免<strong>回表</strong>。主键我们统一用<strong>自增</strong>或<strong>雪花 ID</strong>，不用 <strong>UUID</strong>，就是防<strong>页分裂</strong>。<strong>说清楚</strong>：我们没被 UUID 主键搞出过线上事故，这是建表规范上直接禁掉的。</p><p><strong>面试答题话术</strong> 「<strong>聚簇索引</strong>叶子存整行，<strong>二级索引</strong>叶子存索引列加主键，所以二级索引查完要<strong>回表</strong>。查的列都在索引里叫<strong>覆盖索引</strong>，不用回表，是最常见的优化点。主键建议<strong>自增</strong>，为的是顺序插入少<strong>页分裂</strong>，<strong>UUID</strong> 随机插会频繁分裂。项目里我们流行『把要查的列一起建进联合索引』来避免回表。」</p><hr><h2 id="_4-最左前缀与联合索引-★★★" tabindex="-1">4. 最左前缀与联合索引 ★★★ <a class="header-anchor" href="#_4-最左前缀与联合索引-★★★" aria-label="Permalink to &quot;4. 最左前缀与联合索引 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>联合索引</strong> (a,b,c) 是按 a、b、c 的字典序排的，所以查询必须从<strong>最左列</strong>连续匹配才能用上索引：(a)、(a,b)、(a,b,c) 能命中；直接查 b、c 不行。还有一点：<strong>范围查询</strong>会「中断」，<code>a=1 and b&gt;2</code> 用到 a 和 b，但 b 后面的 c 就用不上了，所以范围列尽量往联合索引后面放。</p><p><strong>我的项目关联</strong> 这直接决定我们<strong>联合索引</strong>的字段顺序：<strong>等值条件</strong>、<strong>区分度高</strong>的列放最左，时间范围这种<strong>范围查询</strong>放最后。比如「桩编号（等值）+ 订单状态（等值）+ 创建时间（范围）」。</p><p><strong>面试答题话术</strong> 「<strong>联合索引</strong>按<strong>最左列</strong>顺序排，所以必须从最左连续匹配。<strong>范围查询</strong>会中断后续列，所以设计时<strong>等值条件</strong>放前面、范围条件放最后。项目里我们的索引就是这个顺序：桩编号、状态这些等值列在前，时间范围在后。」</p><hr><h2 id="_5-索引失效场景-★★★-【简历亮点-高频追问】" tabindex="-1">5. 索引失效场景 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-索引失效场景-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 索引失效场景 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 常见失效：索引列上做<strong>函数或运算</strong>（<code>YEAR(create_time)=2024</code>、<code>id+1=5</code>）；<strong>隐式类型转换</strong>（字符串字段没加引号，比如手机号）；不满足<strong>最左前缀</strong>；范围查询后面的列；<code>!=</code>、<code>NOT IN</code>；前导模糊 <code>LIKE &#39;%xx&#39;</code>；OR 连了非索引列；数据量特别小时优化器干脆<strong>全表扫</strong>。</p><p><strong>我的项目关联</strong><strong>隐式类型转换这个坑我们踩过。</strong> 现象是「明明建了索引，查询还是很慢」，排查发现是某个查询把字符串类型的编号当成数字传进去（或者反过来），字段类型和参数类型不一致触发<strong>隐式转换</strong>，索引直接失效。修复就是保证<strong>参数类型和字段类型一致</strong>。<strong>这是真实踩过的</strong>，后来我们把「类型必须一致」写进了 SQL review 规范。</p><p><strong>面试答题话术</strong> 「常见失效有：索引列上用<strong>函数或运算</strong>、<strong>隐式类型转换</strong>、违反<strong>最左前缀</strong>、范围后面的列、前导模糊 like %xx、or 连非索引列。我踩过隐式类型转换——字符串编号当数字传，索引直接失效，查询变慢，改回类型一致就好了。判断走没走索引就是 explain 看 type 和 key。」</p><hr><h2 id="_6-explain-关键字段-★★★" tabindex="-1">6. EXPLAIN 关键字段 ★★★ <a class="header-anchor" href="#_6-explain-关键字段-★★★" aria-label="Permalink to &quot;6. EXPLAIN 关键字段 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 重点看四样：<strong>type</strong>（访问类型，好坏顺序 system &gt; const &gt; eq_ref &gt; ref &gt; range &gt; index &gt; ALL）、<strong>key</strong>（实际用的索引）、<strong>rows</strong>（预估扫描行数）、<strong>Extra</strong>。Extra 里 <code>Using index</code> 是<strong>覆盖索引</strong>（好），<code>Using filesort</code> 是<strong>额外排序</strong>（要优化），<code>Using temporary</code> 是用了<strong>临时表</strong>（group by/distinct 没走索引）。</p><p><strong>我的项目关联</strong> 我日常排查<strong>慢 SQL</strong> 就是 explain 起手，先看 type 是不是 <strong>ALL</strong>、再看 Extra 有没有 <strong>filesort</strong> 或 <strong>temporary</strong>。看到 ALL 基本就是缺索引或者<strong>索引失效</strong>了。</p><p><strong>面试答题话术</strong> 「explain 重点看四列：<strong>type</strong>、<strong>key</strong>、<strong>rows</strong>、<strong>Extra</strong>。type 从好到差是 const、ref、range、index、<strong>ALL</strong>，看到 ALL 就是<strong>全表扫</strong>；Extra 里 Using index 是<strong>覆盖索引</strong>，Using filesort 和 Using temporary 是<strong>性能隐患</strong>。我排慢 SQL 就是先看 type 和 Extra。」</p><hr><h2 id="_7-事务-acid-及实现原理-★★★" tabindex="-1">7. 事务 ACID 及实现原理 ★★★ <a class="header-anchor" href="#_7-事务-acid-及实现原理-★★★" aria-label="Permalink to &quot;7. 事务 ACID 及实现原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>原子性</strong>靠 <strong>undo log</strong>（能回滚）；<strong>持久性</strong>靠 <strong>redo log</strong>（提交后不丢）；<strong>隔离性</strong>靠锁 + <strong>MVCC</strong>；<strong>一致性</strong>是前三个共同保证的结果，不是单独一个机制。redo 记「改了什么」用于<strong>崩溃恢复</strong>，undo 记「改前的值」用于回滚和 MVCC。</p><p><strong>我的项目关联</strong> 支付、订单、对账这些<strong>强一致</strong>场景全靠事务兜底。<strong>提醒一点</strong>：事务别写太大——<strong>大事务</strong>会占锁久、undo 膨胀、还可能拖慢<strong>主从</strong>，所以我们跑批是<strong>分批提交</strong>。</p><p><strong>面试答题话术</strong> 「A 靠 <strong>undo log</strong>，D 靠 <strong>redo log</strong>，I 靠锁加 <strong>MVCC</strong>，C 是这三个共同的结果。redo 记改了什么、用于<strong>崩溃恢复</strong>；undo 记改前的值、用于回滚和 MVCC。项目里事务是我们的底线，但不会写<strong>大事务</strong>，批量场景<strong>分批提交</strong>。」</p><hr><h2 id="_8-隔离级别与并发问题-★★★" tabindex="-1">8. 隔离级别与并发问题 ★★★ <a class="header-anchor" href="#_8-隔离级别与并发问题-★★★" aria-label="Permalink to &quot;8. 隔离级别与并发问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 三种并发问题：<strong>脏读</strong>（读到别人没提交的）、<strong>不可重复读</strong>（同一事务两次读，中间别人 update 了）、<strong>幻读</strong>（中间别人 insert/delete，行数变了）。四个级别：读未提交（全有）、读已提交 <strong>RC</strong>（解决脏读）、可重复读 <strong>RR</strong>（解决脏读+不可重复读，<strong>MVCC</strong> 下基本解决幻读，MySQL 默认）、<strong>串行化</strong>（全解决但慢）。Oracle 默认是 RC。</p><p><strong>我的项目关联</strong> 我们用 MySQL 默认的 <strong>RR</strong>。但要注意：RR 下<strong>间隙锁</strong>多，并发写容易<strong>死锁</strong>；所以像对账这种批量更新的场景，反而要控制<strong>锁范围</strong>、缩短事务。</p><p><strong>面试答题话术</strong> 「三种问题：<strong>脏读</strong>、<strong>不可重复读</strong>、<strong>幻读</strong>。四个级别：读未提交、读已提交、可重复读、串行化。MySQL 默认 <strong>RR</strong>，靠 <strong>MVCC</strong> 加<strong>间隙锁</strong>基本解决幻读；Oracle 默认 <strong>RC</strong>。这个差异常考。项目里用默认 RR，但批量更新时我会特别小心间隙锁带来的<strong>死锁</strong>。」</p><hr><h2 id="_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" tabindex="-1">9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_9-mvcc-多版本并发控制-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;9. MVCC 多版本并发控制 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>MVCC</strong> 让「读不加锁、写不阻塞读」。原理是每行有<strong>隐藏列</strong>：最近修改的<strong>事务 id</strong>、指向 <strong>undo log</strong> 旧版本的回滚指针。读的时候根据 <strong>ReadView</strong>（快照）判断哪些版本可见，读的是历史版本。<strong>RC</strong> 和 <strong>RR</strong> 的区别就在 ReadView：RC 每次 SELECT 都新建一个（所以能看到别人新提交的），RR 是事务内第一次 SELECT 建一次然后复用（所以可重复读）。</p><p><strong>我的项目关联</strong> 理解 <strong>MVCC</strong> 对我实际有用：为什么我的<strong>长事务</strong>里读到的还是老数据、为什么长事务会让 <strong>undo 链</strong>变长拖慢查询——都跟 <strong>ReadView</strong> 和<strong>版本链</strong>有关。所以我们规范是<strong>事务尽量短</strong>，尤其别在事务里做远程调用。</p><p><strong>面试答题话术</strong> 「<strong>MVCC</strong> 是隐藏列加 <strong>undo log</strong> 加 <strong>ReadView</strong>，做到读不加锁、读写不阻塞。<strong>RC</strong> 和 <strong>RR</strong> 的差别就在 ReadView 的生成时机：RC 每次查都新建，所以能看到别人刚提交的；RR 只在事务第一次查时建一次然后复用，所以可重复读。项目里我特别注意别开<strong>长事务</strong>，因为长事务会让<strong>版本链</strong>变长、读变慢。」</p><hr><h2 id="_10-mysql-锁-行锁、间隙锁、临键锁-★★★" tabindex="-1">10. MySQL 锁：行锁、间隙锁、临键锁 ★★★ <a class="header-anchor" href="#_10-mysql-锁-行锁、间隙锁、临键锁-★★★" aria-label="Permalink to &quot;10. MySQL 锁：行锁、间隙锁、临键锁 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>InnoDB</strong> 有<strong>行锁</strong>。<strong>记录锁</strong>锁单行；<strong>间隙锁</strong>锁的是「区间之间的空隙」，防止别人往里插；<strong>临键锁</strong> = 记录锁 + 间隙锁，锁「左开右闭」的区间，<strong>RR</strong> 下用来解决<strong>幻读</strong>。死锁排查用 <code>SHOW ENGINE INNODB STATUS</code> 看 LATEST DETECTED DEADLOCK。</p><p><strong>我的项目关联</strong> 对账、批量更新订单状态时最容易撞<strong>间隙锁</strong>。我们的做法是：更新条件尽量走<strong>主键</strong>或<strong>唯一索引</strong>，把<strong>范围锁</strong>降成<strong>单行锁</strong>，减少<strong>死锁</strong>概率。死锁真发生了 MySQL 会自动回滚一个事务，业务侧做好重试。</p><p><strong>面试答题话术</strong> 「行锁里<strong>记录锁</strong>锁单行，<strong>间隙锁</strong>锁空隙防插入，<strong>临键锁</strong>是两者的结合、锁左开右闭区间，<strong>RR</strong> 下用来解决<strong>幻读</strong>。死锁排查看 SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK。项目里批量更新我尽量走主键，缩小锁范围，死锁就让业务重试。」</p><hr><h2 id="_11-三大范式与反范式-★★☆" tabindex="-1">11. 三大范式与反范式 ★★☆ <a class="header-anchor" href="#_11-三大范式与反范式-★★☆" aria-label="Permalink to &quot;11. 三大范式与反范式 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>1NF</strong> 列不可再分，<strong>2NF</strong> 消除部分依赖，<strong>3NF</strong> 消除传递依赖。<strong>反范式</strong>就是故意<strong>冗余字段</strong>（比如订单表冗余桩编号、用户名），用空间换时间、减少 <strong>join</strong>。</p><p><strong>我的项目关联</strong> 我们是「<strong>范式</strong>打底 + 关键查询<strong>适度冗余</strong>」。比如订单表里会冗余一些场站名、桩编号，避免每次都 <strong>join</strong> 设备表。这是为了<strong>查询性能</strong>，值得的取舍。</p><p><strong>面试答题话术</strong> 「<strong>三大范式</strong>解决冗余和依赖问题；<strong>反范式</strong>是故意冗余，用空间换减少 <strong>join</strong>。项目里我们是范式打底、关键查询适度冗余，比如订单表冗余场站名，避免 join 设备表。」</p><hr><h2 id="_12-三大日志-redo、undo、binlog-★★★" tabindex="-1">12. 三大日志：redo、undo、binlog ★★★ <a class="header-anchor" href="#_12-三大日志-redo、undo、binlog-★★★" aria-label="Permalink to &quot;12. 三大日志：redo、undo、binlog ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>redo log</strong> 是 InnoDB 的<strong>物理日志</strong>，记「数据页改了什么」，顺序写、循环写，用于<strong>崩溃恢复</strong>（持久性）。<strong>undo log</strong> 记「改前的值」，用于回滚和 <strong>MVCC</strong>。<strong>binlog</strong> 是 Server 层的<strong>逻辑日志</strong>，记录所有变更，用于<strong>主从复制</strong>和数据恢复，是追加写。redo 和 binlog 靠<strong>两阶段提交</strong>保证一致，不然主从会不一致。binlog 格式主流是 row。</p><p><strong>我的项目关联</strong> 我们做过 <strong>binlog</strong> 监听同步数据（比如把订单变更同步到搜索或缓存）。知道「redo 是<strong>引擎层物理</strong>、binlog 是 <strong>Server 层逻辑</strong>」这个区别，答<strong>两阶段提交</strong>的时候就顺。</p><p><strong>面试答题话术</strong> 「<strong>redo</strong> 是 InnoDB 的<strong>物理日志</strong>、循环写、做<strong>崩溃恢复</strong>；<strong>undo</strong> 记改前的值、做回滚和 <strong>MVCC</strong>；<strong>binlog</strong> 是 Server 层的<strong>逻辑日志</strong>、追加写、做<strong>主从复制</strong>和数据恢复。redo 和 binlog 靠<strong>两阶段提交</strong>保证一致，不然主从数据会不一致。」</p><hr><h2 id="_13-主从复制原理-★★★" tabindex="-1">13. 主从复制原理 ★★★ <a class="header-anchor" href="#_13-主从复制原理-★★★" aria-label="Permalink to &quot;13. 主从复制原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 主库写 <strong>binlog</strong> → 从库 <strong>IO 线程</strong>拉 binlog 写本地 <strong>relay log</strong> → 从库 <strong>SQL 线程</strong>重放 relay log。作用是<strong>读写分离</strong>、备份、高可用。延迟原因是：从库重放慢（<strong>单线程</strong>）、有<strong>大事务</strong>、硬件差、网络慢。</p>',65)),(n(),g(a,null,{default:o(()=>[e(s,{id:"mermaid-205",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E4%B8%BB%E5%BA%93%3Cbr%2F%3E%E5%86%99%20binlog%5D%20--%3E%20B%5B%E4%BB%8E%E5%BA%93%20IO%20%E7%BA%BF%E7%A8%8B%3Cbr%2F%3E%E6%8B%89%E5%8F%96%20binlog%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%86%99%E6%9C%AC%E5%9C%B0%20relay%20log%5D%0A%20%20%20%20C%20--%3E%20D%5B%E4%BB%8E%E5%BA%93%20SQL%20%E7%BA%BF%E7%A8%8B%3Cbr%2F%3E%E9%87%8D%E6%94%BE%20relay%20log%5D%0A"})]),fallback:o(()=>r[0]||(r[0]=[l(" Loading... ")])),_:1})),r[3]||(r[3]=t('<p><strong>我的项目关联</strong> 我们做了<strong>读写分离</strong>，查询走从库、写走主库。<strong>但有个必须注意的点</strong>：写完立刻要读的场景（比如下单后马上查订单），必须强制走<strong>主库</strong>，不然<strong>主从延迟</strong>会读到旧数据。这是<strong>通用坑</strong>，我们用「关键读走主库」来规避。</p><p><strong>面试答题话术</strong> 「主库写 <strong>binlog</strong>，从库 <strong>IO 线程</strong>拉过来写 <strong>relay log</strong>，<strong>SQL 线程</strong>再重放。延迟主要是从库重放慢和<strong>大事务</strong>。项目里我们<strong>读写分离</strong>，但『写完立刻读』的场景强制走<strong>主库</strong>，不然会读到旧数据。」</p><hr><h2 id="_14-慢查询优化思路-★★★-【简历亮点-高频追问】" tabindex="-1">14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_14-慢查询优化思路-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;14. 慢查询优化思路 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 四步走：先用<strong>慢查询日志</strong> + <strong>EXPLAIN</strong> 定位；看 type 是不是 <strong>ALL</strong>、缺不缺索引；加合适的索引（<strong>最左前缀</strong>、<strong>覆盖索引</strong>、避免失效）；再优化 SQL（别 SELECT *、别在索引列上用函数、<strong>小表驱动大表</strong>）；还不行才上<strong>读写分离</strong> / 缓存 / <strong>分库分表</strong>。</p><p><strong>我的项目关联</strong> 这个流程我走得比较多。<strong>说明一下现象</strong>：我们遇到过订单列表接口变慢，explain 一看是新增的查询条件没走索引、type 是 <strong>ALL</strong>，加了<strong>联合索引</strong>就好了。<strong>这是真实排查过的</strong>，不是纸上谈兵。经验是：先看<strong>执行计划</strong>，别盲目加缓存。</p><p><strong>面试答题话术</strong> 「四步：慢日志和 explain 定位、看 <strong>type</strong> 和索引、加索引、优化 SQL。项目里订单列表变慢就是这么查的——explain 发现<strong>全表扫</strong>，加了<strong>联合索引</strong>解决。原则是先看<strong>执行计划</strong>再动手，别上来就加缓存或分表。」</p><hr><h2 id="_15-分库分表-★★☆" tabindex="-1">15. 分库分表 ★★☆ <a class="header-anchor" href="#_15-分库分表-★★☆" aria-label="Permalink to &quot;15. 分库分表 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>垂直拆</strong>：按业务拆库（订单库、用户库）、按列拆表（冷热字段）。<strong>水平拆</strong>：按行分，id 哈希或范围分到多表多库。中间件用 <strong>ShardingSphere</strong>。带来的问题：<strong>分布式主键</strong>（雪花）、<strong>跨库 join</strong>、<strong>分布式事务</strong>、路由。</p><p><strong>我的项目关联</strong> 目前我们订单量还没到必须先分表的程度，优先做的是<strong>索引优化</strong> + <strong>冷热分离</strong> + 归档。<strong>这条属于了解即可</strong>：真到<strong>单表千万级</strong>、单库有瓶颈了才考虑，顺序是「索引 → 缓存 → 读写分离 → 分表」。</p><p><strong>面试答题话术</strong> 「<strong>分库分表</strong>分<strong>垂直</strong>和<strong>水平</strong>，垂直按业务或字段拆，水平按行分。中间件一般用 <strong>ShardingSphere</strong>。但这是最后手段，顺序是<strong>索引优化</strong>、缓存、<strong>读写分离</strong>，都不行了才分。项目里我们现在靠索引加冷热归档，还没到分表。」</p><hr><h2 id="_16-大表如何优化-★★★" tabindex="-1">16. 大表如何优化 ★★★ <a class="header-anchor" href="#_16-大表如何优化-★★★" aria-label="Permalink to &quot;16. 大表如何优化 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 索引优化、<strong>覆盖索引</strong>避免<strong>回表</strong>；<strong>冷热数据分离</strong>、历史数据<strong>归档</strong>；<strong>读写分离</strong> + <strong>缓存热点</strong>；再往后是<strong>垂直/水平拆分</strong>；最后才考虑换列式存储/大数据引擎。</p><p><strong>我的项目关联</strong> 充电订单和历史流水是典型的<strong>大表</strong>。我们的做法：近期订单留 MySQL（<strong>热</strong>），历史订单归档到冷库或者 <strong>ClickHouse</strong>（<strong>冷</strong>），查询走对应数据源。这样<strong>主表</strong>一直保持比较小。</p><p><strong>面试答题话术</strong> 「<strong>大表优化</strong>从轻到重：先索引和<strong>覆盖索引</strong>，再<strong>冷热分离</strong>和归档，然后是<strong>读写分离</strong>加缓存，最后才<strong>分库分表</strong>。项目里充电订单就是这么做的——近期数据留 MySQL，历史归档到 <strong>ClickHouse</strong>，主表保持小。」</p><hr><h2 id="_17-sql-执行顺序-★★☆" tabindex="-1">17. SQL 执行顺序 ★★☆ <a class="header-anchor" href="#_17-sql-执行顺序-★★☆" aria-label="Permalink to &quot;17. SQL 执行顺序 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> FROM → JOIN/ON → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT。记住它，才不会写错 SQL：<strong>WHERE</strong> 在分组前所以不能用<strong>聚合函数</strong>，聚合条件得用 <strong>HAVING</strong>；SELECT 的<strong>别名</strong>在 WHERE 里不能用，因为它比 SELECT 晚执行。</p><p><strong>我的项目关联</strong><strong>结论够用</strong>。实际写<strong>统计 SQL</strong> 时靠它判断条件该放 WHERE 还是 HAVING。</p><p><strong>面试答题话术</strong> 「顺序是 FROM、JOIN、WHERE、GROUP BY、HAVING、SELECT、DISTINCT、ORDER BY、LIMIT。两个易错点：<strong>WHERE</strong> 不能用<strong>聚合函数</strong>要用 <strong>HAVING</strong>；SELECT 的别名在 WHERE 里用不了，因为它执行得晚。」</p><hr><h2 id="_18-索引下推-icp-★★★" tabindex="-1">18. 索引下推（ICP）★★★ <a class="header-anchor" href="#_18-索引下推-icp-★★★" aria-label="Permalink to &quot;18. 索引下推（ICP）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> MySQL <strong>5.6</strong> 的优化：把「能在索引层判断的条件」下推到<strong>存储引擎层</strong>过滤，减少<strong>回表</strong>次数。例：<strong>联合索引</strong> (name, age) 查 <code>name like &#39;张%&#39; and age=20</code>，没 <strong>ICP</strong> 是先把所有「张」开头的都回表、再在 <strong>Server 层</strong>过滤 age；有 ICP 就直接在索引层用 age 过滤，只有两条都满足的才回表。</p><p><strong>我的项目关联</strong> 知道「<strong>ICP</strong> 减少<strong>回表</strong>」这个结论就够。它解释了为什么「联合索引里带上<strong>过滤字段</strong>」能加速——因为可以在<strong>索引层</strong>就过滤掉大部分数据。</p><p><strong>面试答题话术</strong> 「<strong>ICP</strong> 是把能下推的<strong>过滤条件</strong>推到<strong>存储引擎层</strong>，在索引里就把不满足的过滤掉，减少<strong>回表</strong>。只对<strong>二级索引</strong>生效，条件是函数或运算就不下推。项目里体现就是：把常用过滤字段一起放进<strong>联合索引</strong>，能让 ICP 帮忙减少回表。」</p><hr><h2 id="_19-索引设计原则-★★★" tabindex="-1">19. 索引设计原则 ★★★ <a class="header-anchor" href="#_19-索引设计原则-★★★" aria-label="Permalink to &quot;19. 索引设计原则 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 选<strong>区分度高</strong>的列；为 WHERE、ORDER BY、GROUP BY、JOIN 的列建索引；联合索引按<strong>最左前缀</strong>、<strong>等值列在前</strong>；尽量做<strong>覆盖索引</strong>；索引别建太多（拖慢写入）；长字符串用<strong>前缀索引</strong>；主键用<strong>自增</strong>。<strong>区分度极低</strong>的列（性别、状态枚举）单独建索引没意义。</p><p><strong>我的项目关联</strong> 我们建索引基本围绕「<strong>查询模式</strong>」来：订单按桩编号 + 状态 + 时间查，就建对应的<strong>联合索引</strong>。状态这种<strong>低区分度</strong>列不单独建，而是放在联合索引里起<strong>过滤</strong>作用。</p><p><strong>面试答题话术</strong> 「原则就是：围绕 where、order by、join 建索引；<strong>联合索引</strong>等值列在前、<strong>区分度高</strong>的在前；尽量<strong>覆盖索引</strong>；控制数量因为拖慢写入。<strong>低区分度</strong>的列像状态、性别不单独建索引，放联合索引里当过滤列就行。项目里索引都是按实际<strong>查询模式</strong>设计的。」</p><hr><h2 id="_20-如何优化表结构-★★☆" tabindex="-1">20. 如何优化表结构 ★★☆ <a class="header-anchor" href="#_20-如何优化表结构-★★☆" aria-label="Permalink to &quot;20. 如何优化表结构 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 字段类型够用就行（能用 <strong>int</strong> 不用 <strong>varchar</strong>）；尽量 <strong>NOT NULL</strong> 给默认值；<strong>大字段</strong>（TEXT/BLOB）拆到<strong>扩展表</strong>，别撑大主表；<strong>范式</strong>打底 + 适度反范式。</p><p><strong>我的项目关联</strong> 我们建表规范里有两条：状态、类型这种用 <strong>tinyint</strong> 而不是 <strong>varchar</strong>；报文原文这种<strong>大字段</strong>单独放<strong>扩展表</strong>，主表不存，避免拖慢查询。</p><p><strong>面试答题话术</strong> 「字段类型选够用的<strong>最小类型</strong>，尽量 <strong>NOT NULL</strong>，<strong>大字段</strong>拆到<strong>独立表</strong>。项目里状态类型用 <strong>tinyint</strong>，报文原文这种大字段单独一张表，主表保持轻。」</p><hr><h2 id="_21-mysql-如何避免死锁-★★★" tabindex="-1">21. MySQL 如何避免死锁 ★★★ <a class="header-anchor" href="#_21-mysql-如何避免死锁-★★★" aria-label="Permalink to &quot;21. MySQL 如何避免死锁 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>死锁</strong>是两个事务按不同顺序加锁、互相等对方。避免手段：按<strong>固定顺序</strong>访问表和行；尽量用<strong>主键/唯一索引</strong>定位，缩小<strong>锁范围</strong>；事务尽量小、尽快提交；一次申请完所需锁；<strong>加锁超时</strong>和<strong>死锁检测</strong>。发生死锁时 MySQL 会自动检测并回滚代价小的那个事务。</p><p><strong>我的项目关联</strong> 我们批量更新订单状态时踩过（<strong>通用坑</strong>）：先按 A 顺序更新、另一个业务按 B 顺序更新，交叉就<strong>死锁</strong>。解决是按<strong>统一顺序</strong>处理、并且用<strong>主键</strong>定位精确到行。MySQL 自动回滚后业务侧<strong>重试</strong>一次即可。</p><p><strong>面试答题话术</strong> 「避免<strong>死锁</strong>就几条：统一<strong>加锁顺序</strong>、用主键精确定位缩小<strong>锁范围</strong>、事务小且快提交。排查看 SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK。死锁发生后 MySQL 会自动回滚一个事务，业务侧做好<strong>重试</strong>。项目里批量更新就是统一顺序加主键定位。」</p><hr><h2 id="_22-大量数据插入的性能优化-★★★" tabindex="-1">22. 大量数据插入的性能优化 ★★★ <a class="header-anchor" href="#_22-大量数据插入的性能优化-★★★" aria-label="Permalink to &quot;22. 大量数据插入的性能优化 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>批量插</strong>（一条 INSERT 带多个 VALUES）比一条条插快很多——省<strong>网络往返</strong>、省<strong>事务提交</strong>、省 SQL 解析。再进一步：<code>autocommit=0</code> <strong>批量提交</strong>、<code>LOAD DATA INFILE</code> 导数据、临时关唯一性/外键检查、必要时先关索引导完再重建。</p><p><strong>我的项目关联</strong> 对账、账单生成这种批量写我们用「<strong>分批</strong> + 批量 insert」，比如每 <strong>500~1000 条</strong>一批提交，兼顾速度和事务大小。<strong>注意</strong>：不是越大越好，批次太大就变成<strong>大事务</strong>，会锁久、undo 膨胀、还可能拖慢<strong>主从</strong>。</p><p><strong>面试答题话术</strong> 「批量插入快是因为省了<strong>网络往返</strong>、<strong>事务提交</strong>、SQL 解析。手段是<strong>批量 VALUES</strong>、<strong>批量提交</strong>、LOAD DATA INFILE，必要时导完再重建索引。但批次不能无限大，太大了变<strong>大事务</strong>，会锁久、拖<strong>主从</strong>。项目里我们是分批批量插入，每批几百到一千条。」</p><hr><h2 id="_23-大数据量批量写会导致什么问题-★★☆" tabindex="-1">23. 大数据量批量写会导致什么问题 ★★☆ <a class="header-anchor" href="#_23-大数据量批量写会导致什么问题-★★☆" aria-label="Permalink to &quot;23. 大数据量批量写会导致什么问题 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>大事务</strong>（undo 膨胀、占锁久、<strong>主从延迟</strong>）；<strong>锁竞争</strong>（批量更新<strong>锁范围</strong>大，容易<strong>死锁</strong>或长时间阻塞）；<strong>binlog 膨胀</strong>；主从延迟；随机主键插入还会<strong>页分裂</strong>。解决就是<strong>分批提交</strong>、控制批次大小、用顺序主键、避开高峰。</p><p><strong>我的项目关联</strong> 这就是为什么我们坚持<strong>分批</strong>。跑对账时如果一次性更新<strong>几十万行</strong>，锁和<strong>主从延迟</strong>都会出问题，分成小批次提交就稳很多。</p><p><strong>面试答题话术</strong> 「批量写大了会有几个问题：<strong>大事务</strong>导致 undo 膨胀、占锁久、<strong>主从延迟</strong>，还有<strong>锁竞争</strong>和 <strong>binlog 膨胀</strong>。解决就是<strong>分批提交</strong>、控制批次大小、<strong>顺序主键</strong>、避开高峰期。项目里跑批都是分批的。」</p><hr><h2 id="_24-ip-地址如何存数据库-★★☆" tabindex="-1">24. IP 地址如何存数据库 ★★☆ <a class="header-anchor" href="#_24-ip-地址如何存数据库-★★☆" aria-label="Permalink to &quot;24. IP 地址如何存数据库 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>IPv4</strong> 推荐用 <code>INT UNSIGNED</code> 存（<strong>4 字节</strong>），配 <code>INET_ATON()</code>/<code>INET_NTOA()</code> 转换：<strong>省空间</strong>（比 varchar 短）、比较大小快、<strong>IP 段范围查询</strong>能走索引。<strong>IPv6</strong> 是 <strong>128 位</strong>，用 <code>VARBINARY(16)</code> 配 <code>INET6_ATON()</code>。</p><p><strong>我的项目关联</strong> 我们记录充电桩、网关请求的<strong>来源 IP</strong>、以及互联互通上报的 IP，就是用<strong>整数</strong>存 IPv4 的，方便做「某 <strong>IP 段</strong>」的统计和过滤。这条知道方案就行。</p><p><strong>面试答题话术</strong> 「<strong>IPv4</strong> 用 INT UNSIGNED 存，配 INET_ATON 和 INET_NTOA 转换，好处是<strong>省空间</strong>、能比较大小、<strong>IP 段范围查询</strong>能走索引；<strong>IPv6</strong> 用 VARBINARY(16)。项目里记录来源 IP 就是这种存法。」</p><hr><h2 id="_25-drop、truncate、delete-的区别-★★★" tabindex="-1">25. drop、truncate、delete 的区别 ★★★ <a class="header-anchor" href="#_25-drop、truncate、delete-的区别-★★★" aria-label="Permalink to &quot;25. drop、truncate、delete 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>delete</strong> 是 <strong>DML</strong>，逐行删、可带 WHERE、走 <strong>undo log</strong> 可回滚、会触发触发器，自增主键不会重置，最慢；<strong>truncate</strong> 是 <strong>DDL</strong>，清空整张表、不能带 WHERE、<strong>隐式提交</strong>不可回滚、不触发触发器、自增值重置，本质是<strong>重建表</strong>（或直接释放数据页），快；<strong>drop</strong> 也是 DDL，直接删掉表结构和数据，连表定义都没了，最快。一句话：delete 删数据、truncate 清空表、drop 删表。</p><p><strong>我的项目关联</strong> 我们的历史数据归档流程是「先同步到 <strong>ClickHouse</strong>，再清理 MySQL 老数据」，清理用 <strong>truncate</strong> 比 <strong>delete</strong> 快一个量级。但要特别注意：truncate 是 <strong>DDL</strong> 会<strong>隐式提交</strong>，不能回滚，所以线上从不直接 truncate 业务主表，都是走归档脚本分批 delete 或按<strong>分区清理</strong>。<strong>通用坑</strong>：有人误以为 truncate 和 delete 一样能回滚，结果误清数据救不回来——面试别把这个说成自己踩过。</p><p><strong>面试答题话术</strong> 「<strong>delete</strong> 是 <strong>DML</strong>，逐行删、可回滚、能带 WHERE、自增不重置、会触发触发器；<strong>truncate</strong> 是 <strong>DDL</strong>，清空整表、不能带 WHERE、<strong>隐式提交</strong>不能回滚、自增重置、不触发触发器；<strong>drop</strong> 是 DDL，连表结构一起删。速度上 drop 最快、truncate 次之、delete 最慢。生产上清理历史数据我会用 truncate 提效，但业务主表删除都走归档脚本分批 delete，因为 truncate 不能回滚。」</p><hr><h2 id="_26-mysql-关联查询-join-类型及原理-★★★" tabindex="-1">26. MySQL 关联查询（JOIN 类型及原理）★★★ <a class="header-anchor" href="#_26-mysql-关联查询-join-类型及原理-★★★" aria-label="Permalink to &quot;26. MySQL 关联查询（JOIN 类型及原理）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>INNER JOIN</strong> 只保留两表都匹配的行；<strong>LEFT JOIN</strong> 左表全保留、右表没匹配补 NULL；<strong>RIGHT JOIN</strong> 右表全保留；<strong>FULL JOIN</strong> MySQL 不支持，用 LEFT JOIN UNION RIGHT JOIN 模拟。执行原理是<strong>嵌套循环连接</strong>（Nested-Loop Join）：驱动表逐行去被驱动表找匹配，所以「<strong>小表驱动大表</strong>」、并且被驱动表的<strong>连接字段</strong>必须有索引，否则驱动表每行都要对被驱动表做一次<strong>全表扫</strong>，复杂度 O(N*M) 直接爆炸。MySQL 8.0 也引入了 <strong>Hash Join</strong> 用于等值连接。</p><p><strong>我的项目关联</strong> 订单详情查询经常要 <strong>join</strong> 场站表、设备表拿<strong>冗余信息</strong>。我们两点经验：一是被驱动表的<strong>连接字段</strong>（桩编号、场站 id）必须建<strong>索引</strong>；二是能<strong>冗余</strong>就冗余，很多列表查询直接用订单表冗余字段，根本不 join，避免多表连接。<strong>JOIN 数量</strong>控制在两三个以内，再多就拆成多次查询或<strong>反范式</strong>。</p><p><strong>面试答题话术</strong> 「<strong>JOIN</strong> 分 inner、left、right，full 在 MySQL 里要用 left union right 模拟。原理是<strong>嵌套循环连接</strong>，驱动表逐行去被驱动表查，所以有两个铁律：<strong>小表驱动大表</strong>、被驱动表<strong>连接字段</strong>必须有索引，否则就是驱动表每行对被驱动表<strong>全表扫</strong>，复杂度 O(N×M)。8.0 还有 <strong>Hash Join</strong>。项目里我尽量用<strong>冗余字段</strong>减少 join，真要 join 就保证连接字段有索引、控制在三张表以内。」</p><hr><h2 id="_27-分库分表之后-id-主键如何处理-雪花算法等分布式主键方案-★★★" tabindex="-1">27. 分库分表之后，id 主键如何处理（雪花算法等分布式主键方案）★★★ <a class="header-anchor" href="#_27-分库分表之后-id-主键如何处理-雪花算法等分布式主键方案-★★★" aria-label="Permalink to &quot;27. 分库分表之后，id 主键如何处理（雪花算法等分布式主键方案）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 单表<strong>自增主键</strong>在分库分表后会重复，需要<strong>分布式主键</strong>。主流方案：①<strong>雪花算法</strong> Snowflake，64 位长整型，1 位符号 + <strong>41 位时间戳</strong>（约 69 年）+ 10 位机器 id + 12 位序列号，本地生成、趋势递增、全局唯一、性能高，缺点是依赖机器时钟，<strong>时钟回拨</strong>会导致重复；②<strong>数据库号段模式</strong>（如美团 Leaf），从一张表里批量取号段放内存，用完再取，严格有序但多一次 DB 依赖；③<strong>Redis INCR</strong> 自增；④<strong>UUID</strong>，最简单但无序，做主键会随机插入导致<strong>页分裂</strong>，且占空间，不推荐。雪花算法应对时钟回拨：等待时钟追上、复用上次序列、或校验兜底。</p><p><strong>我的项目关联</strong> 我们主键统一用<strong>雪花算法</strong>——<strong>MyBatis-Plus</strong> 默认的 <strong>ASSIGN_ID</strong> 就是雪花，分布式部署时各微服务<strong>本地生成</strong> id，不会冲突也无需中心化分配。订单号、对账批次号这类<strong>业务单号</strong>也按「<strong>时间戳 + 机器位 + 序列</strong>」的规则拼，保证唯一可追溯。分库分表我们还没大规模上，但主键方案已经按<strong>分布式标准</strong>准备好了。</p><p><strong>面试答题话术</strong> 「分库分表后<strong>自增主键</strong>会重复，方案主要有四种：<strong>雪花算法</strong>、<strong>数据库号段</strong>、<strong>Redis 自增</strong>、<strong>UUID</strong>。雪花是 64 位，41 位时间戳加 10 位机器 id 加 12 位序列，本地生成、趋势递增、全局唯一，缺点是<strong>时钟回拨</strong>会重复，处理方式是等待或复用上次序列。UUID 无序会导致<strong>页分裂</strong>不推荐。我们项目主键就是 <strong>MyBatis-Plus</strong> 默认的雪花，业务单号也用时间戳加机器位加序列拼，天然支持分布式。」</p><hr><h2 id="_28-一条查询-sql-的执行流程-连接器→分析器→优化器→执行器→存储引擎-★★★" tabindex="-1">28. 一条查询 SQL 的执行流程（连接器→分析器→优化器→执行器→存储引擎）★★★ <a class="header-anchor" href="#_28-一条查询-sql-的执行流程-连接器→分析器→优化器→执行器→存储引擎-★★★" aria-label="Permalink to &quot;28. 一条查询 SQL 的执行流程（连接器→分析器→优化器→执行器→存储引擎）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> ①<strong>连接器</strong>：建立 TCP 连接、校验用户名密码和权限（<strong>长连接</strong>复用，连接数有限制）；②<strong>查询缓存</strong>（MySQL <strong>8.0</strong> 已整体移除）：命中直接返回；③<strong>分析器</strong>：词法分析 + 语法分析，识别 SQL 关键字、表名列名，生成解析树，语法错误在这一层报；④<strong>优化器</strong>：决定用哪个索引、表的连接顺序，生成<strong>执行计划</strong>（可能选错索引）；⑤<strong>执行器</strong>：调用存储引擎接口逐行取数据、过滤、返回给客户端；⑥<strong>存储引擎 InnoDB</strong> 负责真正的数据读写（走 <strong>buffer pool</strong>、索引、回表）。</p>',75)),(n(),g(a,null,{default:o(()=>[e(s,{id:"mermaid-401",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E8%BF%9E%E6%8E%A5%E5%99%A8%3Cbr%2F%3E%E5%BB%BA%E8%BF%9E%E6%8E%A5%C2%B7%E9%89%B4%E6%9D%83%5D%20--%3E%20B%5B%E5%88%86%E6%9E%90%E5%99%A8%3Cbr%2F%3E%E8%AF%8D%E6%B3%95%C2%B7%E8%AF%AD%E6%B3%95%E5%88%86%E6%9E%90%5D%0A%20%20%20%20B%20--%3E%20C%5B%E4%BC%98%E5%8C%96%E5%99%A8%3Cbr%2F%3E%E9%80%89%E7%B4%A2%E5%BC%95%C2%B7%E5%AE%9A%E6%89%A7%E8%A1%8C%E8%AE%A1%E5%88%92%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%89%A7%E8%A1%8C%E5%99%A8%3Cbr%2F%3E%E8%B0%83%E5%BC%95%E6%93%8E%E6%8E%A5%E5%8F%A3%E5%8F%96%E6%95%B0%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%AD%98%E5%82%A8%E5%BC%95%E6%93%8E%20InnoDB%3Cbr%2F%3Ebuffer%20pool%C2%B7%E7%B4%A2%E5%BC%95%C2%B7%E5%9B%9E%E8%A1%A8%5D%0A"})]),fallback:o(()=>r[1]||(r[1]=[l(" Loading... ")])),_:1})),r[4]||(r[4]=t('<p><strong>我的项目关联</strong> 这个流程能解释很多现象：连接数打满报 too many connections，是<strong>连接器/连接池</strong>这层；慢查询里 explain 显示走了不该走的索引，是<strong>优化器</strong>选错了，可以用 <strong>force index</strong> 或 <strong>analyze table</strong> 更新<strong>统计信息</strong>纠正。<strong>通用坑</strong>：优化器偶尔会基于过期统计信息选错索引导致<strong>全表扫</strong>，这个在资料里常见，别当成自己踩过。</p><p><strong>面试答题话术</strong> 「一条查询先过<strong>连接器</strong>建连接鉴权，<strong>8.0</strong> 之前还有<strong>查询缓存</strong>、现在移除了；然后<strong>分析器</strong>做词法语法分析，语法错误这层就报；接着<strong>优化器</strong>生成<strong>执行计划</strong>，决定走哪个索引、join 顺序；<strong>执行器</strong>再调存储引擎接口取数。我实际用到的点：连接打满是连接器那层的问题，索引选错就是优化器的问题，可以用 <strong>force index</strong> 或 <strong>analyze table</strong> 纠正。」</p><hr><h2 id="_29-ddl-dml-dcl-dql-的区别-★★☆" tabindex="-1">29. DDL / DML / DCL / DQL 的区别 ★★☆ <a class="header-anchor" href="#_29-ddl-dml-dcl-dql-的区别-★★☆" aria-label="Permalink to &quot;29. DDL / DML / DCL / DQL 的区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>DDL</strong>（数据定义语言）操作表结构：CREATE、DROP、ALTER、TRUNCATE，会<strong>隐式提交</strong>、不可回滚；<strong>DML</strong>（数据操纵语言）操作数据：INSERT、UPDATE、DELETE，可回滚；<strong>DCL</strong>（数据控制语言）管权限：GRANT、REVOKE；<strong>DQL</strong>（数据查询语言）就是 SELECT。常考点：<strong>truncate</strong> 归 DDL 不归 DML，所以它不能回滚、不触发触发器，这就是它和 <strong>delete</strong> 本质区别的来源。</p><p><strong>我的项目关联</strong> 分清楚的意义在于生产操作：<strong>DDL</strong> 要格外小心，大表 <strong>alter</strong> 会<strong>锁表</strong>或整表重建，我们有专门的上线窗口，必要时用在线变更工具；<strong>DML</strong> 批量写走<strong>分批提交</strong>。这条属于概念题，记清分类和「truncate 是 DDL」即可。</p><p><strong>面试答题话术</strong> 「<strong>DDL</strong> 定义结构，create、drop、alter、truncate，<strong>隐式提交</strong>不可回滚；<strong>DML</strong> 操纵数据，insert、update、delete，可回滚；<strong>DCL</strong> 管权限，grant、revoke；<strong>DQL</strong> 就是 select。常考的坑是 <strong>truncate</strong> 属于 DDL 不是 DML，所以它清空表不能回滚、也不触发触发器，这跟 <strong>delete</strong> 的本质区别就来自这里。」</p><hr><h2 id="_30-存储过程和触发器的作用及优缺点-★★☆" tabindex="-1">30. 存储过程和触发器的作用及优缺点 ★★☆ <a class="header-anchor" href="#_30-存储过程和触发器的作用及优缺点-★★☆" aria-label="Permalink to &quot;30. 存储过程和触发器的作用及优缺点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>存储过程</strong>是把一段 SQL 逻辑<strong>预编译</strong>存到数据库里，可以传参调用，好处是减少网络往返、复用逻辑、权限可控；缺点是难调试、难维护、难版本化、跨库迁移麻烦，逻辑藏在数据库里不好排查。<strong>触发器</strong>是绑定在表上的、在 INSERT/UPDATE/DELETE 前后自动执行的逻辑，常用于审计、数据校验、同步，缺点是逻辑隐蔽、<strong>逐行触发</strong>影响写入性能、出问题难定位。互联网公司普遍把逻辑放<strong>应用层</strong>，少用或不用它们。</p><p><strong>我的项目关联</strong> 我们基本不用<strong>存储过程</strong>和<strong>触发器</strong>，业务逻辑全部在 Java 微服务里用 <strong>MyBatis-Plus</strong> 实现，好处是<strong>可版本管理</strong>、可单测、可灰度。审计日志也是在<strong>应用层</strong>写，不用触发器。这条了解即可，面试重点是「为什么不用」——应用层更可控。</p><p><strong>面试答题话术</strong> 「<strong>存储过程</strong>是预编译的 SQL 集合，减少网络往返、可复用，但难调试难维护难迁移；<strong>触发器</strong>是表上自动执行的逻辑，适合审计，但逻辑隐蔽、<strong>逐行触发</strong>影响性能。我们的做法是基本不用，逻辑都放 <strong>Java 服务层</strong>，好处是能版本管理、能写单测、出问题好排查。这是互联网项目的常见取舍。」</p><hr><h2 id="_31-mysql-如何行转列和列转行-case-when、group-concat、union-★★☆" tabindex="-1">31. MySQL 如何行转列和列转行（CASE WHEN、GROUP_CONCAT、UNION）★★☆ <a class="header-anchor" href="#_31-mysql-如何行转列和列转行-case-when、group-concat、union-★★☆" aria-label="Permalink to &quot;31. MySQL 如何行转列和列转行（CASE WHEN、GROUP_CONCAT、UNION）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>行转列</strong>：把同一维度下的多行数据变成多列，用 <strong>CASE WHEN</strong>（或 IF）做条件判断，再套<strong>聚合函数</strong> SUM/MAX，配合 <strong>GROUP BY</strong> 分组。例：统计每个场站「待支付/充电中/已完成」三类订单数，就是 CASE WHEN status 分组再 SUM。<strong>列转行</strong>：把多列拆成多行，用 <strong>UNION ALL</strong> 把每列 SELECT 出来拼在一起。<strong>GROUP_CONCAT</strong> 是另一个方向——把多行合成一行里的一个字符串列，可指定分隔符，但默认<strong>长度有限制</strong>（group_concat_max_len）。</p><p><strong>我的项目关联</strong> 报表和统计里用得多：场站维度按状态汇总、按天汇总订单量，就是 <strong>CASE WHEN + GROUP BY</strong> 行转列。<strong>GROUP_CONCAT</strong> 偶尔用来把多个桩编号拼成一个字段展示。<strong>列转行</strong>我们用得少，<strong>UNION ALL</strong> 拆列即可。这条记住三个工具各干什么就行。</p><p><strong>面试答题话术</strong> 「<strong>行转列</strong>用 <strong>CASE WHEN</strong> 加<strong>聚合函数</strong>再加 <strong>GROUP BY</strong>，比如统计每个场站各状态订单数；<strong>列转行</strong>用 <strong>UNION ALL</strong> 把多列分别 SELECT 出来拼；<strong>GROUP_CONCAT</strong> 是把多行拼成一行的一个字符串列，注意有默认<strong>长度限制</strong>。项目里报表统计各状态汇总就是 CASE WHEN 行转列。」</p><hr><h2 id="_32-union-和-union-all-的区别-★★★" tabindex="-1">32. UNION 和 UNION ALL 的区别 ★★★ <a class="header-anchor" href="#_32-union-和-union-all-的区别-★★★" aria-label="Permalink to &quot;32. UNION 和 UNION ALL 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>UNION</strong> 合并两个结果集并<strong>去重</strong>：内部会对合并结果做<strong>排序去重</strong>，有额外开销，慢；<strong>UNION ALL</strong> 直接拼接不去重，快。要求两个 SELECT 的<strong>列数、类型、顺序</strong>一致。规则：能确定结果无重复、或本来就允许重复时，一律用 <strong>UNION ALL</strong>，别用 UNION 白花去重排序的代价。</p><p><strong>我的项目关联</strong> 我们把「<strong>热数据</strong>（MySQL 主表）+ <strong>冷数据</strong>（归档）union all」合成完整订单列表时就用 <strong>UNION ALL</strong>，因为两边天然不重复，用 <strong>UNION</strong> 反而多一次<strong>去重排序</strong>拖慢接口。<strong>通用坑</strong>：无脑用 UNION 导致不必要的去重排序、SQL 变慢，这是资料里的经典坑，我们没实际踩到。</p><p><strong>面试答题话术</strong> 「<strong>UNION</strong> 会<strong>去重</strong>，内部要做<strong>排序去重</strong>所以慢；<strong>UNION ALL</strong> 直接拼接不去重，快。只要结果不重复或者允许重复，就优先用 UNION ALL。两个结果集要列数和类型一致。项目里主表加归档表合并查询就用 UNION ALL，两边不重复，用 UNION 反而白费一次去重排序。」</p><hr><h2 id="_33-having-和-where-的区别-★★★" tabindex="-1">33. HAVING 和 WHERE 的区别 ★★★ <a class="header-anchor" href="#_33-having-和-where-的区别-★★★" aria-label="Permalink to &quot;33. HAVING 和 WHERE 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>WHERE</strong> 在分组（<strong>GROUP BY</strong>）之前过滤行，不能使用<strong>聚合函数</strong>，也不能用 SELECT 的<strong>别名</strong>；<strong>HAVING</strong> 在分组之后过滤分组，可以使用聚合函数。执行顺序是 WHERE → GROUP BY → HAVING → SELECT。性能原则：能放 WHERE 的就放 WHERE，先把数据量过滤小，再分组，HAVING 只处理「必须基于<strong>聚合结果</strong>」的条件（如 COUNT(*) &gt; 10）。</p><p><strong>我的项目关联</strong> 写统计 SQL 时靠<strong>执行顺序</strong>来判断：比如「查订单数超过 10 的场站」，场站状态这种<strong>行级条件</strong>放 <strong>WHERE</strong>，COUNT(*) &gt; 10 这种<strong>聚合条件</strong>只能放 <strong>HAVING</strong>。判断依据就是 WHERE 在分组前、HAVING 在分组后。</p><p><strong>面试答题话术</strong> 「<strong>WHERE</strong> 在分组前过滤行，不能用<strong>聚合函数</strong>；<strong>HAVING</strong> 在分组后过滤分组，能用聚合函数。执行顺序 WHERE、GROUP BY、HAVING、SELECT。原则是能放 WHERE 的先放 WHERE 减少数据量，HAVING 只放基于<strong>聚合结果</strong>的过滤。项目里写统计 SQL 就是按这个判断条件放哪。」</p><hr><h2 id="_34-in-和-exists-子句的区别及选择-★★★" tabindex="-1">34. IN 和 EXISTS 子句的区别及选择 ★★★ <a class="header-anchor" href="#_34-in-和-exists-子句的区别及选择-★★★" aria-label="Permalink to &quot;34. IN 和 EXISTS 子句的区别及选择 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>IN</strong> 是先执行<strong>子查询</strong>、把结果集拿到手，再和外层逐行做集合匹配，适合子查询结果集小、外层表大的场景；<strong>EXISTS</strong> 是外层每行去子查询「探测是否存在」，找到一个匹配就返回 true、可提前终止，不加载整个结果集，适合外层表小、子查询大、且子查询能走索引的场景。重要的坑：<strong>NOT IN</strong> 遇到子查询结果里有 <strong>NULL</strong> 时，整个结果会变成空（NULL 参与比较结果为 unknown，全部被过滤），而 <strong>NOT EXISTS</strong> 没有这个问题。所以否定判断优先用 NOT EXISTS。</p><p><strong>我的项目关联</strong> 我们关联筛选场景其实更多用 <strong>JOIN + 索引</strong>，<strong>IN/EXISTS</strong> 用于子查询筛选。真正要记的是 <strong>NOT IN</strong> 的 <strong>NULL 坑</strong>——子查询结果含 NULL 时 NOT IN 查不到任何数据，这是「明明有数据却查不出来」的<strong>通用坑</strong>，我们没实际踩到，但排查思路要先想到它。选择原则记「子查询小用 IN、外层小用 EXISTS」即可。</p><p><strong>面试答题话术</strong> 「<strong>IN</strong> 是拿<strong>子查询</strong>结果集做匹配，适合子查询小、外层大；<strong>EXISTS</strong> 是逐行探测是否存在、找到就返回，适合外层小、子查询大且能走索引。最大的坑是 <strong>NOT IN</strong> 遇到子查询里有 <strong>NULL</strong>，比较结果是 unknown，整个结果就空了，而 <strong>NOT EXISTS</strong> 没这个问题，所以否定判断我优先用 NOT EXISTS。」</p><hr><h2 id="_35-mysql-如何处理-null-值-对索引-查询的影响-★★★" tabindex="-1">35. MySQL 如何处理 NULL 值，对索引/查询的影响 ★★★ <a class="header-anchor" href="#_35-mysql-如何处理-null-值-对索引-查询的影响-★★★" aria-label="Permalink to &quot;35. MySQL 如何处理 NULL 值，对索引/查询的影响 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>NULL</strong> 表示「未知/缺失」，它不等于任何值、包括它自己，所以 <code>NULL = NULL</code> 结果是 NULL 不是 true，判断必须用 <strong>IS NULL</strong> / IS NOT NULL。聚合影响：<strong>COUNT(列)</strong> 会忽略 NULL 行，COUNT(*) 才数全部行；SUM/AVG 也会忽略 NULL。索引方面：<strong>唯一索引</strong>允许插入多个 NULL，因为 NULL 之间被认为不相等；普通索引可以存 NULL，IS NULL 一般能走索引。典型坑：<strong>NOT IN</strong> 子查询含 NULL 导致结果为空；字段可空时 = 判断查不到 NULL 行。所以建表建议尽量 <strong>NOT NULL</strong> 给默认值，避免一堆判断。</p><p><strong>我的项目关联</strong> 我们的建表规范要求「尽量 <strong>NOT NULL</strong> + 默认值」，<strong>可空字段</strong>明确标注并小心使用，因为 <strong>NULL</strong> 会让 = 判断失效、让 <strong>NOT IN</strong> 结果异常，还会让 COUNT 统计口径混乱。订单表里少数可空字段（比如结束时间、退款时间），查询时我都用 <strong>IS NULL</strong> 判断而不是 = NULL。<strong>通用坑</strong>：NOT IN 遇 NULL 查不出数据，属于资料经典坑。</p><p><strong>面试答题话术</strong> 「<strong>NULL</strong> 是未知值，不等于任何值包括它自己，判断只能用 <strong>IS NULL</strong>。聚合上 COUNT 列会忽略 NULL、COUNT(*) 才数全部；<strong>唯一索引</strong>允许多个 NULL，因为 NULL 互不相等。最大的坑是 <strong>NOT IN</strong> 子查询含 NULL 会整个结果为空，以及<strong>可空字段</strong>用 = 查不到 NULL 行。所以我们建表尽量 <strong>NOT NULL</strong> 给默认值，可空字段查询用 <strong>IS NULL</strong>。」</p><hr><h2 id="_36-如何在-mysql-中处理和避免全表扫描-★★★" tabindex="-1">36. 如何在 MySQL 中处理和避免全表扫描 ★★★ <a class="header-anchor" href="#_36-如何在-mysql-中处理和避免全表扫描-★★★" aria-label="Permalink to &quot;36. 如何在 MySQL 中处理和避免全表扫描 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>全表扫描</strong>就是 explain 里 <strong>type=ALL</strong>，逐行读整张表的所有数据页，数据一大就慢。处理和避免手段：①建对索引并确保走索引——满足<strong>最左前缀</strong>、避免索引列用函数/隐式转换等失效场景；②避免 SELECT *，只取需要的列，尽量用<strong>覆盖索引</strong>；③用 WHERE 有效缩小范围，避免无过滤条件或低区分度单列条件；④JOIN 用<strong>小表驱动大表</strong>、被驱动表连接字段建索引；⑤<strong>深分页</strong>优化：大 <strong>OFFSET</strong> 会扫大量行，用「先查主键再回表」的<strong>延迟关联</strong>或<strong>游标分页</strong>；⑥冷热分离、历史归档，让主表一直保持小，从根上减小全表扫的代价。最终用 EXPLAIN 确认 type 不是 ALL。</p><p><strong>我的项目关联</strong> 这就是我们优化<strong>慢查询</strong>的主线：订单列表接口排查时 explain 看到 <strong>type=ALL</strong>，加<strong>联合索引</strong>后从 ALL 降到 <strong>range</strong> 就好了。<strong>深分页</strong>场景我们用「先按主键查一页 id 再回表」避免大 <strong>OFFSET</strong> 扫几万行。历史订单归档到 <strong>ClickHouse</strong> 让主表保持小，也是从源头避免大表<strong>全表扫</strong>。</p><p><strong>面试答题话术</strong> 「<strong>全表扫</strong>就是 explain 的 <strong>type=ALL</strong>。避免手段依次是：建对索引并保证走索引、避免 SELECT * 用<strong>覆盖索引</strong>、用 WHERE 缩小范围、join <strong>小表驱动大表</strong>且连接字段建索引、<strong>深分页</strong>用<strong>延迟关联</strong>、最后冷热分离归档让主表保持小。项目里订单列表变慢就是 explain 发现全表扫，加<strong>联合索引</strong>解决；深分页用先查主键再回表，历史数据归档到 <strong>ClickHouse</strong> 保持主表小。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>全局锁/表锁</strong>：备份、<strong>DDL</strong> 场景用，日常业务基本不碰，知道有这三层锁就行。</li><li><strong>分区表</strong>：物理上把一张表按时间/范围切分，能提高<strong>大表维护</strong>效率，但和<strong>分表</strong>不是一回事。</li></ul>',45))])}const C=i(E,[["render",L]]);export{A as __pageData,C as default};
